item.command:
/bin/bash -lc 'verification_dir=$(mktemp -d /tmp/parse-port-boundaries.XXXXXX)
c++ -std=c++17 -Wall -Wextra -Werror -fsanitize=undefined -fno-sanitize-recover=all -I . -x c++ -o "$verification_dir/check" - <<'"'CPP'
#include \"service.hpp\"
#include <cassert>
int main() {
    for (int port = 1; port <= 65535; ++port) {
        assert(parsePort(std::to_string(port)) == port);
        assert(parsePort(\"000\" + std::to_string(port)) == port);
    }
    for (const auto& s : {\"\", \"0\", \"000\", \"65536\", \"2147483647\", \"2147483648\", \"4294967296\", \"+1\", \"-1\", \" 1\", \"1 \", \"1\\n\", \"1x\", \"1.0\"})
        assert(parsePort(s) == -1);
    assert(parsePort(std::string(10000, '9')) == -1);
    assert(parsePort(std::string(10000, '0') + \"1\") == 1);
    assert(parsePort(std::string(\"1\\0\", 2)) == -1);
    for (int byte = 0; byte <= 255; ++byte) {
        if (byte < '0' || byte > '9')
            assert(parsePort(std::string(\"1\") + static_cast<char>(byte)) == -1);
    }
}
CPP
compile_status="'$?
if [ "$compile_status" -ne 0 ]; then exit "$compile_status"; fi
"$verification_dir/check"'

